<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {Mic,Play,Plus,Save,Download,AudioLines,RefreshCw,Check,Clock} from 'lucide-vue-next'
import {voiceApi} from '../voice/operations'
const data=ref(null),busy=ref(false),error=ref(''),notice=ref(''),selected=ref(null),form=ref(blank()),values=ref({primeiro_nome:'Marina',nome:'Marina Silva',empresa:'Zyrex',assunto:'seu atendimento',campanha:'Relacionamento'}),view=ref('templates'),conversation=ref(''),sending=ref(false),comparison=ref([])
let timer=null,disposed=false,sendKey=null
function blank(){return {engine:'kokoro',name:'',body:'Olá, {primeiro_nome}! Aqui é a equipe {empresa}. Tentamos falar com você. Entre em contato quando puder.',voice:'pf_dora',speed:1}}
const fields=computed(()=>[...new Set([...form.value.body.matchAll(/\{([a-z][a-z0-9_]{0,39})\}/g)].map(m=>m[1]))])
const engine=computed(()=>data.value?.engines?.[form.value.engine||'kokoro'])
const engineName=id=>data.value?.engines?.[id||'kokoro']?.name||'Kokoro'
const renderedLength=computed(()=>form.value.body.replace(/\{([a-z][a-z0-9_]{0,39})\}/g,(_,k)=>values.value[k]||'').length)
const comparing=computed(()=>comparison.value.some(a=>a.status==='generating'))
function switchEngine(id){form.value.engine=id;form.value.voice=Object.keys(data.value.engines[id].voices)[0]}
const pending=computed(()=>selected.value?.status==='generating')
const api=(p='',method='GET',body)=>voiceApi('/speech'+p,method,body)
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){data.value=await api()}
function edit(t){form.value=t?{engine:'kokoro',...t,speed:Number(t.speed)}:blank();notice.value='';error.value=''}
async function save(){const t=await api('/templates'+(form.value.id?'/'+form.value.id:''),form.value.id?'PUT':'POST',form.value);form.value={engine:'kokoro',...t,speed:Number(t.speed)};await load();notice.value='Template salvo. Você pode personalizar os dados a cada geração.'}
const payload=()=>({...form.value,name:form.value.name||'Prévia de voz',values:Object.fromEntries(fields.value.map(k=>[k,values.value[k]||'']))})
async function compare(){
 comparison.value=[]
 const body=payload();const results=await Promise.allSettled(['kokoro','chatterbox'].map(engine=>api('/generate','POST',{...body,engine,voice:engine===form.value.engine?form.value.voice:Object.keys(data.value.engines[engine].voices)[0]})))
 results.forEach((r,i)=>{comparison.value.push(r.status==='fulfilled'?r.value:{engine:['kokoro','chatterbox'][i],status:'failed',error:r.reason.message})})
 await load();poll()
}
async function generate(){selected.value=await api('/generate','POST',{...form.value,name:form.value.name||'Prévia de voz',values:Object.fromEntries(fields.value.map(k=>[k,values.value[k]||'']))});await load();poll()}
function choose(a){selected.value=a;poll()}
async function sendAudio(){if(sending.value)return;sending.value=true;error.value='';try{const fingerprint=selected.value.id+conversation.value;if(sendKey?.fingerprint!==fingerprint)sendKey={fingerprint,key:crypto.randomUUID()};const r=await voiceApi('/conversations/'+conversation.value+'/send','POST',{idempotency_key:sendKey.key,speech_asset_id:selected.value.id});notice.value=['sent','delivered','read','accepted','queued'].includes(r.status)?'Áudio encaminhado. Acompanhe a entrega em Conversas.':'Resultado: '+r.status+'. Confira em Conversas antes de repetir.'}catch(e){error.value=e.message}finally{sending.value=false}}
function poll(){clearTimeout(timer);const jobs=[selected.value,...comparison.value].filter(a=>a?.id&&a.status==='generating');if(disposed||!jobs.length)return;timer=setTimeout(async()=>{try{const results=await Promise.allSettled([...new Set(jobs.map(a=>a.id))].map(id=>api('/assets/'+id)));if(disposed)return;let completed=false;for(const r of results){if(r.status==='rejected'){error.value=r.reason.message;continue}const a=r.value;if(selected.value?.id===a.id)selected.value=a;comparison.value=comparison.value.map(old=>old.id===a.id?a:old);completed||=a.status!=='generating'}if(completed)await load()}catch(e){error.value=e.message}finally{poll()}},3000)}
const audioUrl=format=>'/api/voice/speech/assets/'+selected.value.id+'/'+format
const date=s=>new Date(s.replace(' ','T')+(s.includes('Z')?'':'Z')).toLocaleString('pt-BR')
onMounted(()=>run(load));onBeforeUnmount(()=>{disposed=true;clearTimeout(timer)})
</script>
<template>
<section class="speech-studio">
 <header class="speech-hero"><div class="speech-mark"><AudioLines :size="30"/></div><div><span class="eyebrow">A VOZ DA SUA MARCA</span><h2>Escreva. Ouça. Conecte.</h2><p>Transforme suas mensagens em áudio, com vozes em português e os dados de cada contato.</p></div><span class="engine-badge"><span :class="{ready:engine?.service.ready}"></span>{{engine?.service.ready?'Voz própria conectada':'Verificando serviço de voz'}}</span></header>
 <div v-if="error" class="error" role="alert">{{error}}</div><div v-if="notice" class="speech-notice" role="status"><Check :size="16"/>{{notice}}</div>
 <p v-if="data&&!engine?.service.ready" class="speech-notice">O serviço de voz está indisponível. Seus templates continuam salvos. <button class="secondary" @click="run(load)">Verificar novamente</button></p>
 <div class="speech-layout" v-if="data">
  <aside class="speech-library"><div class="speech-library-head"><h3>Sua biblioteca</h3><button class="secondary" aria-label="Criar template de voz" @click="edit(null)"><Plus :size="16"/></button></div><div class="speech-tabs"><button :class="{active:view==='templates'}" @click="view='templates'">Templates <small>{{data.templates.length}}</small></button><button :class="{active:view==='audio'}" @click="view='audio'">Áudios <small>{{data.assets.length}}</small></button></div>
   <template v-if="view==='templates'"><button v-for="t in data.templates" :key="t.id" class="speech-item" :class="{selected:form.id===t.id}" @click="edit(t)"><Mic :size="19"/><span><strong>{{t.name}}</strong><small>{{engineName(t.engine)}} · {{data.engines?.[t.engine||'kokoro']?.voices[t.voice]}}</small></span></button><p v-if="!data.templates.length" class="speech-empty">Seu primeiro template começa ao lado. Salve o texto e reutilize com outros contatos.</p></template>
   <template v-else><button v-for="a in data.assets" :key="a.id" class="speech-item" :class="{selected:selected?.id===a.id}" @click="choose(a)"><Play v-if="a.status==='ready'" :size="18"/><Clock v-else :size="18"/><span><strong>{{a.name}}</strong><small>{{engineName(a.engine)}} · {{a.status==='ready'?a.duration+' s':a.status==='generating'?'Gerando áudio':'Geração não concluída'}} · {{date(a.created_at)}}</small></span></button><p v-if="!data.assets.length" class="speech-empty">Gere uma prévia para ouvir e baixar seu primeiro áudio.</p></template>
  </aside>
  <div class="speech-main"><form class="speech-editor" @submit.prevent="run(generate)"><div class="speech-editor-heading"><h3>{{form.id?'Editar template':'Nova mensagem de voz'}}</h3><span>Português · Brasil</span></div><div class="speech-engines" role="group" aria-label="Motor de voz"><button v-for="(item,id) in data.engines" :key="id" type="button" :aria-pressed="form.engine===id" :class="{active:form.engine===id}" @click="switchEngine(id)"><strong>{{item.name}}</strong><small>{{item.description}}</small><span>{{item.service.ready?(item.service.busy?'Gerando outro áudio':'Disponível'):'Indisponível'}}</span></button></div><label>Nome da mensagem<input v-model="form.name" maxlength="160" placeholder="Ex.: Recado de retorno"></label><label>O que a voz deve dizer?<textarea v-model="form.body" maxlength="1200" rows="5" required aria-label="Texto da mensagem de voz"/></label><div class="speech-text-foot"><span>Personalize com {primeiro_nome}, {empresa} ou seus próprios campos.</span><small>{{renderedLength}} / {{engine?.max_chars}} preenchidos</small></div><div class="speech-options"><label>Voz<select v-model="form.voice"><option v-for="(name,key) in engine?.voices" :key="key" :value="key">{{name}}</option></select></label><label>Velocidade<select v-model.number="form.speed"><option :value="0.8">Mais calma</option><option :value="0.9">Calma</option><option :value="1">Natural</option><option :value="1.1">Ágil</option><option :value="1.2">Mais ágil</option></select></label></div>
   <details v-if="fields.length" class="speech-samples" open><summary>Dados para esta prévia <small>{{fields.length}} campos</small></summary><p>Preencha os exemplos. Gerar áudio não cadastra nem contata ninguém.</p><div class="speech-values"><label v-for="field in fields" :key="field">{{'{'+field+'}'}}<input v-model="values[field]" :aria-label="'Valor de '+field" maxlength="300" required></label></div></details>
   <p v-if="form.engine==='chatterbox'" class="speech-note">Modelo dedicado ao português brasileiro. Nesta VM, a geração pode levar alguns minutos. Use até 300 caracteres após preencher as variáveis.</p><div class="speech-actions"><button class="secondary" type="button" :disabled="busy||!form.name.trim()" @click="run(save)"><Save :size="16"/> Salvar template</button><button class="primary" :disabled="busy||pending||comparing||!engine?.service.ready||renderedLength>engine.max_chars"><Mic :size="17"/>{{pending?'Gerando áudio…':'Gerar e ouvir'}}</button><button class="secondary" type="button" :disabled="busy||pending||comparing||renderedLength>300||!data.engines?.kokoro.service.ready||!data.engines?.chatterbox.service.ready" @click="run(compare)"><AudioLines :size="17"/>Comparar os dois</button></div><p class="speech-note">A comparação usa o mesmo texto e velocidade nos dois motores (até 300 caracteres preenchidos).</p>
  </form>
  <section v-if="comparison.length" class="speech-comparison" aria-label="Comparação de vozes"><article v-for="(a,i) in comparison" :key="a.engine||i"><span class="eyebrow">OUÇA E COMPARE</span><h3>{{engineName(a.engine)}}</h3><p v-if="a.status==='generating'" role="status">Gerando a prévia… {{a.engine==='chatterbox'?'Pode levar alguns minutos.':''}}</p><p v-else-if="a.status!=='ready'" role="alert">{{a.error||'Áudio indisponível. Gere novamente.'}}</p><template v-else><audio controls preload="none" :src="'/api/voice/speech/assets/'+a.id+'/mp3'" :aria-label="'Ouvir '+engineName(a.engine)"/><p>{{a.duration}} s de áudio · gerado em {{Number(a.generation_seconds).toFixed(1)}} s</p><button class="secondary" @click="choose(a)">Selecionar e baixar</button></template></article></section>
  <section class="speech-player" aria-label="Prévia de áudio"><div class="speech-player-icon"><AudioLines :size="28"/></div><div v-if="!selected"><h3>Sua mensagem ganha voz aqui</h3><p>Gere uma prévia ou escolha um áudio da biblioteca.</p></div><div v-else class="speech-player-body"><h3>{{selected.name}}</h3><small>{{engineName(selected.engine)}}</small><p v-if="pending" role="status">Gerando em nosso servidor. Você pode continuar trabalhando e voltar à biblioteca.</p><p v-else-if="selected.status==='failed'" role="alert">{{selected.error||'Não foi possível gerar. Tente novamente.'}}</p><p v-else-if="selected.status==='expired'">Este áudio expirou. Gere uma nova versão.</p><template v-else-if="selected.status==='ready'"><audio :key="selected.id" controls preload="none" :src="audioUrl('mp3')" aria-label="Ouvir áudio gerado"/><div class="speech-downloads"><a :href="audioUrl('mp3')" download="mensagem.mp3"><Download :size="14"/> MP3</a><a :href="audioUrl('wav')" download="mensagem.wav"><Download :size="14"/> WAV · telefonia</a><a :href="audioUrl('ogg')" download="mensagem.ogg"><Download :size="14"/> OGG · WhatsApp</a><small>{{selected.duration}} segundos</small></div><details class="speech-send"><summary>Enviar este áudio pelo WhatsApp</summary><p>Escolha uma conversa aberta, atribuída a você e com resposta recebida nas últimas 24 horas. O envio usa o número dessa conversa.</p><label>Conversa<select v-model="conversation" aria-label="Conversa para enviar áudio"><option value="">Selecione uma conversa</option><option v-for="c in data.conversations||[]" :key="c.id" :value="c.id">{{c.phone}}</option></select></label><button class="primary" :disabled="!conversation||sending" @click="sendAudio">{{sending?'Enviando…':'Enviar áudio agora'}}</button><p v-if="!data.conversations?.length">Assuma uma conversa elegível na caixa de atendimento para enviar.</p></details><details><summary>Texto deste áudio</summary><p>{{selected.body}}</p></details></template></div></section>
  <p class="speech-note">Áudios disponíveis por 30 dias. A prévia não faz ligações nem envia WhatsApp. Kokoro e Chatterbox geram a voz em nossa infraestrutura, sem usar créditos de voz da Twilio.</p>
  </div>
 </div><p v-else>Carregando seu estúdio de voz…</p>
</section>
</template>
<style scoped>
.speech-engines,.speech-comparison{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:18px 0}.speech-engines button,.speech-comparison article{padding:18px;border:1px solid #dfe1d5;border-radius:14px;text-align:left;background:#fff;color:#34402f}.speech-engines button{display:block;width:100%}.speech-engines button.active{border-color:#bd953d;background:#fcf8ed;box-shadow:0 0 0 1px #bd953d}.speech-engines strong,.speech-engines small,.speech-engines span{display:block}.speech-engines small{font-size:11px;line-height:1.6;margin:8px 0;color:#717b67}.speech-engines span{font-size:10px;color:#927027}.speech-comparison article{min-width:0}.speech-comparison audio{width:100%;margin-top:12px}.speech-comparison p{font-size:12px;line-height:1.7;color:#717b67}.speech-actions{flex-wrap:wrap}.speech-studio{max-width:1500px;margin:auto}.speech-hero{display:flex;align-items:center;gap:22px;padding:28px;margin-bottom:24px;border-radius:20px;background:linear-gradient(120deg,#1e3530,#293d32);color:#fff}.speech-hero h2{font-size:29px;margin:6px 0 8px}.speech-hero p{margin:0;color:#cbd3c5;font-size:13px}.speech-hero .eyebrow{color:#e7c678}.speech-mark{color:#e4bc63;padding:18px;border:1px solid #ffffff25;border-radius:18px}.engine-badge{margin-left:auto;white-space:nowrap;font-size:11px;display:flex;gap:7px;align-items:center;color:#dfe9dc}.engine-badge span{width:7px;height:7px;border-radius:50%;background:#e0b453}.engine-badge .ready{background:#91c59a}.speech-layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:22px}.speech-library,.speech-editor,.speech-player{background:white;border:1px solid #dfe1d5;border-radius:18px}.speech-library{align-self:start;padding:18px}.speech-library-head,.speech-editor-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.speech-library h3,.speech-editor h3,.speech-player h3{margin:0;font-size:17px}.speech-tabs{display:flex;gap:8px;margin:20px 0 12px}.speech-tabs button{border:0;border-radius:9px;background:#f5f5f0;padding:9px 12px;font-size:12px;color:#6a725f}.speech-tabs .active{background:#f4e9cb;color:#8c641b}.speech-tabs small{margin-left:5px}.speech-item{display:flex;gap:12px;align-items:center;background:white;text-align:left;border:1px solid transparent;border-radius:12px;padding:14px 10px;width:100%;color:#ad822c}.speech-item:hover,.speech-item.selected{border-color:#ddc999;background:#fcf8ed}.speech-item span{min-width:0}.speech-item strong{display:block;font-size:12px;color:#34402f;overflow-wrap:anywhere}.speech-item small{display:block;font-size:10px;color:#7d856f;margin-top:5px}.speech-empty{font-size:12px;color:#818973;line-height:1.8;padding:16px 6px}.speech-main{min-width:0}.speech-editor{padding:26px}.speech-editor-heading{margin-bottom:20px}.speech-editor-heading span{font-size:11px;color:#898d7a}.speech-editor label{display:flex;flex-direction:column;gap:8px;font-size:12px;font-weight:600;margin:16px 0}.speech-editor input,.speech-editor select,.speech-editor textarea{width:100%;min-width:0}.speech-editor textarea{resize:vertical;line-height:1.8}.speech-text-foot{display:flex;gap:16px;justify-content:space-between;color:#888f7c;font-size:11px}.speech-text-foot small{white-space:nowrap}.speech-options,.speech-values{display:grid;grid-template-columns:1fr 1fr;gap:16px}.speech-samples{padding:14px 16px;background:#f8f8f3;border-radius:12px;margin:10px 0 20px}.speech-samples summary{font-size:12px;font-weight:600;cursor:pointer}.speech-samples summary small{font-weight:400;color:#929881;margin-left:8px}.speech-samples p{font-size:11px;color:#848c78}.speech-values label{margin:8px 0}.speech-actions{display:flex;justify-content:flex-end;gap:10px}.speech-player{display:flex;gap:18px;align-items:flex-start;padding:24px;margin-top:20px}.speech-player-icon{padding:14px;background:#f8f0dd;color:#b78e38;border-radius:14px}.speech-player p{font-size:12px;color:#818973;line-height:1.7;margin:8px 0}.speech-player-body{flex:1;min-width:0}.speech-player audio{width:100%;margin:16px 0 8px;height:42px}.speech-player details{font-size:11px;margin-top:14px}.speech-downloads{display:flex;gap:14px;align-items:center;flex-wrap:wrap}.speech-downloads a{font-size:11px;color:#987022;display:flex;gap:5px;align-items:center}.speech-downloads small{font-size:10px;color:#89907c}.speech-send select{width:100%;margin:10px 0}.speech-send{padding:12px;background:#f8f8f2;border-radius:10px}.speech-note{font-size:11px;color:#879079;line-height:1.8;padding:0 6px}.speech-notice{display:flex;align-items:center;gap:10px;padding:14px;background:#eff6eb;border-radius:12px;font-size:12px;margin-bottom:18px}@media(max-width:1000px){.speech-layout{grid-template-columns:230px minmax(0,1fr)}.speech-hero{flex-wrap:wrap}.engine-badge{margin-left:0}}@media(max-width:700px){.speech-engines,.speech-comparison{grid-template-columns:1fr}.speech-layout{grid-template-columns:1fr}.speech-hero{padding:20px;gap:14px}.speech-hero h2{font-size:24px}.speech-mark{display:none}.speech-editor{padding:18px}.speech-options,.speech-values{grid-template-columns:1fr;gap:0}.speech-player{padding:18px;gap:12px}.speech-player-icon{display:none}.speech-actions{flex-wrap:wrap}.speech-text-foot{flex-wrap:wrap}.speech-library{max-height:250px;overflow:auto}}
</style>
